import numpy as np
def equation(t, x, v, params):
    c0,c1,c2,c3,c4,c5,F,G,w,k = params[0],params[1],params[2],params[3],params[4],params[5],params[6],params[7],params[8],params[9]
    poly = c0 + c1*x + c2*v + c3*x**2 + c4*x*v + c5*v**2
    return poly + F*np.cos(w*t + k*x) + G*x*np.cos(w*t + k*x)
